<?php require '../config/database.php';auth();$id=(int)$_GET['id'];$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)die('غير موجود');if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('UPDATE products SET name=?,barcode=?,category=?,purchase_price=?,sale_price=?,quantity=?,min_quantity=?,description=? WHERE id=?');$s->execute([$_POST['name'],$_POST['barcode'],$_POST['category'],(float)$_POST['purchase_price'],(float)$_POST['sale_price'],(int)$_POST['quantity'],(int)$_POST['min_quantity'],$_POST['description'],$id]);header('Location:index.php');exit;}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/style.css"><main><h1>تعديل منتج</h1><form method="post"><label>الاسم</label><input name="name" value="<?=htmlspecialchars($r['name'])?>"><label>الباركود</label><input name="barcode" value="<?=$r['barcode']?>"><label>التصنيف</label><input name="category" value="<?=$r['category']?>"><label>سعر الشراء</label><input type="number" step="0.01" name="purchase_price" value="<?=$r['purchase_price']?>"><label>سعر البيع</label><input type="number" step="0.01" name="sale_price" value="<?=$r['sale_price']?>"><label>الكمية</label><input type="number" name="quantity" value="<?=$r['quantity']?>"><label>الحد الأدنى</label><input type="number" name="min_quantity" value="<?=$r['min_quantity']?>"><label>الوصف</label><textarea name="description"><?=htmlspecialchars($r['description'])?></textarea><button>حفظ</button></form></main>
